// the IF layer converts boost::shared_ptr -> std::shared_ptr via
// sq_ros1_compat::to_std() (no deep copy).

#include "tf2_msgs/TFMessage.h"

namespace tf2_msgs {
namespace msg {
using TFMessage = ::tf2_msgs::TFMessage;
}  // namespace msg
}  // namespace tf2_msgs

